package com.suriya.expensetracker;

import android.content.*;
import android.content.pm.PackageManager;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.util.*;
import java.text.SimpleDateFormat;

/** Snapshot serialization and conservative, transactional merge of backup records. */
final class BackupSnapshot {
    static final String MARKER="Expense Tracker backup", VERSION="1";
    static final String[] TABLES={"transactions","emi_plans","commitments","fuel_cycles","emi_payments","commitment_links","payee_rules","processed"};
    final Context context; final Store store;
    BackupSnapshot(Context c,Store s){context=c;store=s;}
    static boolean identified(String t){return !t.equals("processed")&&!t.equals("payee_rules");}
    static String uid(SQLiteDatabase db,String table,long id){try(Cursor c=db.rawQuery("SELECT uid FROM backup_ids WHERE kind=? AND local_id=?",new String[]{table,""+id})){if(c.moveToFirst())return c.getString(0);}String value=UUID.randomUUID().toString();ContentValues v=new ContentValues();v.put("kind",table);v.put("local_id",id);v.put("uid",value);db.insertOrThrow("backup_ids",null,v);return value;}
    static String date(long ms){return new SimpleDateFormat("dd MMM yyyy",Locale.ENGLISH).format(new Date(ms));}
    static String month(long ms){return new SimpleDateFormat("yyyy-MM",Locale.US).format(new Date(ms));}
    static String money(long paise){return java.math.BigDecimal.valueOf(paise,2).toPlainString();}
    static WorkbookIO.Sheet sheet(TreeMap<String,WorkbookIO.Sheet> months,long ms){String key=month(ms);WorkbookIO.Sheet s=months.get(key);if(s==null){Calendar c=Calendar.getInstance();c.setTimeInMillis(ms);s=new WorkbookIO.Sheet(new SimpleDateFormat("MMM-yyyy",Locale.ENGLISH).format(c.getTime()));months.put(key,s);}return s;}
    static JSONObject fields(Cursor c)throws Exception{JSONObject row=new JSONObject();for(int i=0;i<c.getColumnCount();i++){String name=c.getColumnName(i);if(name.equals("backup_rowid"))continue;switch(c.getType(i)){case Cursor.FIELD_TYPE_NULL:row.put(name,JSONObject.NULL);break;case Cursor.FIELD_TYPE_INTEGER:row.put(name,c.getLong(i));break;case Cursor.FIELD_TYPE_FLOAT:row.put(name,c.getDouble(i));break;case Cursor.FIELD_TYPE_STRING:row.put(name,c.getString(i));break;default:throw new IllegalStateException("Unsupported database field");}}return row;}
    static void metaRow(WorkbookIO.Sheet meta,String type,JSONObject data)throws Exception{String value=data.toString();if(value.length()>32000)throw new IllegalStateException("A backup record is too large for Excel");meta.row(WorkbookIO.t(type),WorkbookIO.t(value));}
    List<WorkbookIO.Sheet> capture()throws Exception{
        if(context.checkSelfPermission(android.Manifest.permission.READ_SMS)==PackageManager.PERMISSION_GRANTED){try{store.recoverSmsLinks(context);}catch(Exception ignored){/* Backup still contains all previously recorded message fingerprints. */}}
        SQLiteDatabase db=store.getWritableDatabase();TreeMap<String,WorkbookIO.Sheet> months=new TreeMap<>();WorkbookIO.Sheet meta=new WorkbookIO.Sheet(WorkbookIO.META);meta.row(WorkbookIO.t(MARKER),WorkbookIO.t(VERSION));JSONObject header=new JSONObject();header.put("created_at",System.currentTimeMillis());header.put("schema",7);metaRow(meta,"header",header);
        db.beginTransaction();try{
            for(String table:TABLES){try(Cursor c=db.rawQuery("SELECT rowid AS backup_rowid,* FROM "+table,null)){while(c.moveToNext()){
                JSONObject data=fields(c),record=new JSONObject();record.put("data",data);long local=c.getLong(c.getColumnIndexOrThrow("backup_rowid"));if(identified(table)){record.put("local",local);record.put("uid",uid(db,table,local));JSONArray aliases=new JSONArray();try(Cursor all=db.rawQuery("SELECT uid FROM backup_ids WHERE kind=? AND local_id=?",new String[]{table,""+local})){while(all.moveToNext())aliases.put(all.getString(0));}record.put("aliases",aliases);}
                if(table.equals("transactions")){try(Cursor link=db.rawQuery("SELECT fingerprint FROM sms_links WHERE transaction_id=?",new String[]{""+local})){if(link.moveToFirst())record.put("sms",link.getString(0));}}
                metaRow(meta,table,record);
            }}}
            try(Cursor c=db.rawQuery("SELECT date,title,bank,kind,category,amount,review FROM transactions ORDER BY date,_id",null)){while(c.moveToNext()){
                WorkbookIO.Sheet sheet=sheet(months,c.getLong(0));sheet.row(WorkbookIO.t("Transaction"),WorkbookIO.t(date(c.getLong(0))),WorkbookIO.t(c.getString(1)),WorkbookIO.t(c.getString(2)),WorkbookIO.t(c.getString(3).equals("Income")?"Credit":"Debit"),WorkbookIO.t(c.getString(4)),WorkbookIO.n(money(c.getLong(5))),WorkbookIO.t(c.getInt(6)==1?"Needs review":"Reviewed"));}}
            try(Cursor c=db.rawQuery("SELECT start_date,start_m,litres_ml,price,end_date,end_m FROM fuel_cycles ORDER BY start_date,_id",null)){while(c.moveToNext()){
                WorkbookIO.Sheet sheet=sheet(months,c.getLong(0));sheet.row(WorkbookIO.t("Fuel"),WorkbookIO.t(date(c.getLong(0))),WorkbookIO.t("Start km: "+FuelPage.decimal(c.getLong(1))),WorkbookIO.t("Litres: "+FuelPage.decimal(c.getLong(2))),WorkbookIO.t(c.isNull(4)?"Cycle open":"End: "+date(c.getLong(4))+" / "+FuelPage.decimal(c.getLong(5))+" km"),WorkbookIO.t("Amount paid"),WorkbookIO.n(money(c.getLong(3))));}}
            try(Cursor c=db.rawQuery("SELECT _id,product,amount,start_date,months FROM emi_plans ORDER BY start_date,_id",null)){while(c.moveToNext()){
                long plan=c.getLong(0);int count=Math.min(c.getInt(4),1200);for(int i=0;i<count;i++){long due=EmiSchedule.due(c.getLong(3),i);if(due>System.currentTimeMillis())break;String status="Unpaid";try(Cursor paid=db.rawQuery("SELECT paid_at FROM emi_payments WHERE plan_id=? AND installment=?",new String[]{""+plan,""+i})){if(paid.moveToFirst())status="Paid: "+date(paid.getLong(0));}
                WorkbookIO.Sheet sheet=sheet(months,due);sheet.row(WorkbookIO.t("EMI"),WorkbookIO.t(date(due)),WorkbookIO.t(c.getString(1)),WorkbookIO.t("Instalment "+(i+1)+" of "+count),WorkbookIO.t(""),WorkbookIO.t("Monthly EMI"),WorkbookIO.n(money(c.getLong(2))),WorkbookIO.t(status));}}}
            db.setTransactionSuccessful();
        }finally{db.endTransaction();}
        for(Map.Entry<String,?> e:context.getSharedPreferences("profile",Context.MODE_PRIVATE).getAll().entrySet()){
            Object value=e.getValue();JSONObject record=new JSONObject();record.put("key",e.getKey());if(value instanceof String){record.put("type","string");record.put("value",value);}else if(value instanceof Boolean){record.put("type","boolean");record.put("value",value);}else if(value instanceof Integer){record.put("type","int");record.put("value",value);}else if(value instanceof Long){record.put("type","long");record.put("value",value);}else if(value instanceof Float){record.put("type","float");record.put("value",((Float)value).doubleValue());}else if(value instanceof Set){record.put("type","strings");JSONArray a=new JSONArray();for(Object item:(Set<?>)value)a.put(String.valueOf(item));record.put("value",a);}else throw new IllegalStateException("Unsupported setting");metaRow(meta,"setting",record);
        }
        ArrayList<WorkbookIO.Sheet> result=new ArrayList<>();for(WorkbookIO.Sheet m:months.values()){m.rows.add(0,Arrays.asList(WorkbookIO.t(m.name+" • Expense Tracker")));m.rows.add(1,Arrays.asList(WorkbookIO.t("Record type"),WorkbookIO.t("Date"),WorkbookIO.t("Description"),WorkbookIO.t("Bank / details"),WorkbookIO.t("Type / details"),WorkbookIO.t("Category / details"),WorkbookIO.t("Amount (₹)"),WorkbookIO.t("Status")));result.add(m);}result.add(meta);return result;
    }
    static final class Parsed {final LinkedHashMap<String,ArrayList<JSONObject>> tables=new LinkedHashMap<>();final ArrayList<JSONObject> settings=new ArrayList<>();int transactions;}
    static Parsed validate(ArrayList<String[]> rows)throws Exception{
        if(rows.isEmpty()||!MARKER.equals(rows.get(0)[0])||!VERSION.equals(rows.get(0)[1]))throw new IllegalArgumentException("This is not a supported Expense Tracker backup.");Parsed out=new Parsed();for(String t:TABLES)out.tables.put(t,new ArrayList<>());boolean header=false;HashSet<String> ids=new HashSet<>();
        for(int i=1;i<rows.size();i++){String[] r=rows.get(i);if(r[0].isEmpty()&&r[1].isEmpty())continue;JSONObject item=new JSONObject(r[1]);if(r[0].equals("header")){if(header||item.getInt("schema")!=7)throw new IllegalArgumentException("Unsupported backup version");header=true;}else if(r[0].equals("setting")){String key=item.getString("key");if(key.length()>200||!Arrays.asList("string","boolean","int","long","float","strings").contains(item.getString("type")))throw new IllegalArgumentException("Invalid setting");out.settings.add(item);}else{ArrayList<JSONObject> list=out.tables.get(r[0]);if(list==null)throw new IllegalArgumentException("Unknown backup record");item.getJSONObject("data");if(identified(r[0])){String uid=item.getString("uid");UUID.fromString(uid);JSONArray aliases=item.getJSONArray("aliases");if(aliases.length()==0||aliases.length()>100)throw new IllegalArgumentException("Invalid backup identifiers");boolean hasMain=false;for(int j=0;j<aliases.length();j++){String alias=aliases.getString(j);UUID.fromString(alias);if(!ids.add(alias))throw new IllegalArgumentException("Duplicate backup identifier");if(uid.equals(alias))hasMain=true;}if(!hasMain)throw new IllegalArgumentException("Missing backup identifier");}if(item.has("sms")&&!item.getString("sms").matches("[0-9a-f]{64}"))throw new IllegalArgumentException("Invalid SMS identifier");list.add(item);}}
        if(!header)throw new IllegalArgumentException("Backup header missing");out.transactions=out.tables.get("transactions").size();return out;
    }
    static long mapped(SQLiteDatabase db,String table,String uid){try(Cursor c=db.rawQuery("SELECT local_id FROM backup_ids WHERE kind=? AND uid=?",new String[]{table,uid})){return c.moveToFirst()?c.getLong(0):-1;}}
    static long mapOld(Map<String,Map<Long,Long>> ids,String table,long old){Map<Long,Long> map=ids.get(table);if(map==null||!map.containsKey(old))throw new IllegalArgumentException("A linked backup record is missing");return map.get(old);}
    static ContentValues toValues(SQLiteDatabase db,String table,JSONObject json,Map<String,Map<Long,Long>> ids)throws Exception{
        HashSet<String> allowed=new HashSet<>();try(Cursor c=db.rawQuery("PRAGMA table_info("+table+")",null)){while(c.moveToNext())allowed.add(c.getString(1));}ContentValues values=new ContentValues();Iterator<String> keys=json.keys();while(keys.hasNext()){String k=keys.next();if(!allowed.contains(k))throw new IllegalArgumentException("Backup has an unexpected field");if(k.equals("_id"))continue;Object value=json.get(k);if(value==JSONObject.NULL){values.putNull(k);continue;}if((table.equals("fuel_cycles")||table.equals("emi_payments")||table.equals("commitment_links"))&&k.equals("expense_id")){values.put(k,mapOld(ids,"transactions",((Number)value).longValue()));continue;}if(table.equals("emi_payments")&&k.equals("plan_id")){values.put(k,mapOld(ids,"emi_plans",((Number)value).longValue()));continue;}if(table.equals("commitment_links")&&k.equals("commitment_id")){values.put(k,mapOld(ids,"commitments",((Number)value).longValue()));continue;}if(value instanceof Integer||value instanceof Long)values.put(k,((Number)value).longValue());else if(value instanceof Double)values.put(k,((Double)value));else if(value instanceof String)values.put(k,(String)value);else throw new IllegalArgumentException("Backup has an invalid value");}return values;
    }
    static void prefPut(SharedPreferences.Editor edit,JSONObject item)throws Exception{String k=item.getString("key"),type=item.getString("type");switch(type){case "string":edit.putString(k,item.getString("value"));break;case "boolean":edit.putBoolean(k,item.getBoolean("value"));break;case "int":edit.putInt(k,item.getInt("value"));break;case "long":edit.putLong(k,item.getLong("value"));break;case "float":edit.putFloat(k,(float)item.getDouble("value"));break;case "strings":JSONArray a=item.getJSONArray("value");Set<String> set=new HashSet<>();for(int i=0;i<a.length();i++)set.add(a.getString(i));edit.putStringSet(k,set);break;default:throw new IllegalArgumentException("Unsupported setting");}}
    int merge(Parsed parsed)throws Exception{
        if(context.checkSelfPermission(android.Manifest.permission.READ_SMS)==PackageManager.PERMISSION_GRANTED){try{store.recoverSmsLinks(context);}catch(Exception ignored){}}
        SQLiteDatabase db=store.getWritableDatabase();Map<String,Map<Long,Long>> ids=new HashMap<>();for(String t:TABLES)ids.put(t,new HashMap<>());int added=0;SharedPreferences profile=context.getSharedPreferences("profile",Context.MODE_PRIVATE);Map<String,?> oldPrefs=profile.getAll();boolean prefsCommitted=false;
        db.beginTransaction();try{
            for(String table:TABLES){for(JSONObject record:parsed.tables.get(table)){JSONObject row=record.getJSONObject("data");
                if(table.equals("processed")){String fp=row.getString("fingerprint");if(!fp.matches("[0-9a-f]{64}"))throw new IllegalArgumentException("Invalid SMS fingerprint");ContentValues v=new ContentValues();v.put("fingerprint",fp);db.insertWithOnConflict(table,null,v,SQLiteDatabase.CONFLICT_IGNORE);continue;}
                if(table.equals("payee_rules")){ContentValues v=toValues(db,table,row,ids);db.insertWithOnConflict(table,null,v,SQLiteDatabase.CONFLICT_IGNORE);continue;}
                String uid=record.getString("uid");long oldId=record.getLong("local");long local=-1;JSONArray aliases=record.getJSONArray("aliases");for(int j=0;j<aliases.length();j++){long existing=mapped(db,table,aliases.getString(j));if(existing>=0&&local>=0&&existing!=local)throw new IllegalArgumentException("A backup record matches multiple existing entries. No data was changed.");if(existing>=0)local=existing;}
                if(table.equals("transactions")&&record.has("sms")){String fingerprint=record.getString("sms");long linked=-1;try(Cursor c=db.rawQuery("SELECT transaction_id FROM sms_links WHERE fingerprint=?",new String[]{fingerprint})){if(c.moveToFirst())linked=c.getLong(0);}if(linked>=0&&local>=0&&linked!=local)throw new IllegalArgumentException("An SMS matches a different existing entry. No data was changed.");if(linked>=0)local=linked;else if(local<0){try(Cursor c=db.rawQuery("SELECT 1 FROM processed WHERE fingerprint=?",new String[]{fingerprint})){if(c.moveToFirst())throw new IllegalArgumentException("An older SMS was already imported, but its transaction cannot be identified safely. No data was changed.");}}}
                if(local<0&&table.equals("transactions")&&!record.has("sms")){try(Cursor c=db.rawQuery("SELECT t._id FROM transactions t WHERE t.amount=? AND t.kind=? AND t.date=? AND t.bank=?",new String[]{row.getString("amount"),row.getString("kind"),row.getString("date"),row.optString("bank","")})){if(c.moveToFirst())throw new IllegalArgumentException("A transaction may already be present from SMS, but the backup cannot identify it safely. No data was changed.");}}
                ContentValues values=toValues(db,table,row,ids);if(local<0){local=db.insertOrThrow(table,null,values);if(table.equals("transactions"))added++;}
                if(ids.get(table).put(oldId,local)!=null)throw new IllegalArgumentException("Duplicate source record");for(int j=0;j<aliases.length();j++){String alias=aliases.getString(j);ContentValues identity=new ContentValues();identity.put("kind",table);identity.put("local_id",local);identity.put("uid",alias);long inserted=db.insertWithOnConflict("backup_ids",null,identity,SQLiteDatabase.CONFLICT_IGNORE);if(inserted==-1&&mapped(db,table,alias)!=local)throw new IllegalArgumentException("Conflicting backup record. No data was changed.");}
                if(table.equals("transactions")&&record.has("sms")){ContentValues link=new ContentValues();link.put("fingerprint",record.getString("sms"));link.put("transaction_id",local);db.insertWithOnConflict("sms_links",null,link,SQLiteDatabase.CONFLICT_IGNORE);}
            }}
            SharedPreferences.Editor edit=profile.edit();for(JSONObject setting:parsed.settings)if(!profile.contains(setting.getString("key")))prefPut(edit,setting);if(!edit.commit())throw new IllegalStateException("Could not restore app settings");prefsCommitted=true;db.setTransactionSuccessful();
        }catch(Exception e){if(prefsCommitted){SharedPreferences.Editor undo=profile.edit().clear();for(Map.Entry<String,?> e2:oldPrefs.entrySet()){Object v=e2.getValue();String k=e2.getKey();if(v instanceof String)undo.putString(k,(String)v);else if(v instanceof Long)undo.putLong(k,(Long)v);else if(v instanceof Integer)undo.putInt(k,(Integer)v);else if(v instanceof Boolean)undo.putBoolean(k,(Boolean)v);else if(v instanceof Float)undo.putFloat(k,(Float)v);else if(v instanceof Set)undo.putStringSet(k,(Set<String>)v);}undo.commit();}throw e;}finally{db.endTransaction();}return added;
    }
}
